test('renderInvoiceText combines discount, voucher, due date, and paid', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'partially_paid',
    number: 'INV-2026-0001',
    dueDate: '2026-11-06',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 10 },
    ],
    voucher: { code: 'PROMO', amount: 2000 },
    payments: [{ amount: 30000, date: '2026-10-15' }],
  };
  const result = renderInvoiceText(invoice);
  assert.equal(result.ok, true);
  const text = result.value;
  const lines = text.split('\n');

  // Check all elements are present
  assert.ok(lines.some(l => l.includes('Discount:')));
  assert.ok(lines.some(l => l.includes('Voucher:')));
  assert.ok(lines.some(l => l.includes('Due:')));
  assert.ok(lines.some(l => l.includes('Paid:')));
});

